if(typeof require==='function'){var Classy=require('./classy');var Box2D=require('./box2d');var Constants=require('./constants');var TankState=require('./tankstate');var Log=require('./log');}var Tank=Classy.newClass().name('Tank');Tank.fields({playerId:null,x:0,y:0,forward:false,back:false,rotation:0,left:false,right:false,fireDown:false,locked:false,b2dbody:null,speed:0.0,rotationSpeed:0.0,roundModel:null,log:null});Tank.constructor(function(tankState,roundModel){this.setTankState(tankState);this.roundModel=roundModel;this.log=Log.create('Tank '+this.playerId);});Tank.methods({setTankState:function(tankState){this.playerId=tankState.getPlayerId();this.x=tankState.getX();this.y=tankState.getY();this.forward=tankState.getForward();this.back=tankState.getBack();this.rotation=tankState.getRotation();this.left=tankState.getLeft();this.right=tankState.getRight();this.fireDown=tankState.getFireDown();this.locked=tankState.getLocked();if(this.b2dbody){this.b2dbody.SetPositionAndAngle(Box2D.Common.Math.b2Vec2.Make(this.x,this.y),this.rotation);if(this.locked){this.b2dbody.SetLinearVelocity(Box2D.Common.Math.b2Vec2.Make(0.0,0.0));this.b2dbody.SetAngularVelocity(0.0);}else{this._computeSpeed();this._computeRotationSpeed();var speedX=Math.sin(this.rotation)*this.speed;var speedY=-Math.cos(this.rotation)*this.speed;this.b2dbody.SetLinearVelocity(Box2D.Common.Math.b2Vec2.Make(speedX,speedY));this.b2dbody.SetAngularVelocity(this.rotationSpeed);}}},getTankState:function(){var ts=TankState.withState(this.playerId,this.x,this.y,this.forward,this.back,this.rotation,this.left,this.right,this.fireDown,this.locked);return ts;},getPlayerId:function(){return this.playerId;},setX:function(x){this.x=x;},getX:function(){return this.x;},setY:function(y){this.y=y;},getY:function(){return this.y;},setForward:function(forward){this.forward=forward;},getForward:function(){if(this.locked){return false;}return this.forward;},setBack:function(back){this.back=back;},getBack:function(){if(this.locked){return false;}return this.back;},setRotation:function(rotation){this.rotation=rotation;},getRotation:function(){return this.rotation;},setLeft:function(left){this.left=left;},getLeft:function(){if(this.locked){return false;}return this.left;},setRight:function(right){this.right=right;},getRight:function(){if(this.locked){return false;}return this.right;},setFireDown:function(fireDown){this.fireDown=fireDown;},getFireDown:function(){if(this.locked){return false;}return this.fireDown;},setLocked:function(locked){this.locked=locked;},getLocked:function(){return this.locked;},setB2DBody:function(b2dbody){this.b2dbody=b2dbody;},getB2DBody:function(){return this.b2dbody;},getSpeed:function(){if(this.locked){return 0.0;}return this.speed;},getRotationSpeed:function(){if(this.locked){return 0.0;}return this.rotationSpeed;},update:function(deltaTime){this.x=this.b2dbody.GetPosition().x;this.y=this.b2dbody.GetPosition().y;this.rotation=this.b2dbody.GetAngle();if(this.locked){this.b2dbody.SetLinearVelocity(Box2D.Common.Math.b2Vec2.Make(0.0,0.0));this.b2dbody.SetAngularVelocity(0.0);}else{this._computeSpeed();this._computeRotationSpeed();var speedX=Math.sin(this.rotation)*this.speed;var speedY=-Math.cos(this.rotation)*this.speed;this.b2dbody.SetLinearVelocity(Box2D.Common.Math.b2Vec2.Make(speedX,speedY));this.b2dbody.SetAngularVelocity(this.rotationSpeed);}},_computeSpeed:function(){this.speed=0.0;var speedModifier=this.roundModel.getModifier(this.playerId,Constants.MODIFIER_TYPES.SPEED);if(this.forward){this.speed+=Constants.TANK.FORWARD_SPEED.m*speedModifier;}if(this.back){this.speed-=Constants.TANK.BACK_SPEED.m*speedModifier;}},_computeRotationSpeed:function(){this.rotationSpeed=0.0;var speedModifier=this.roundModel.getModifier(this.playerId,Constants.MODIFIER_TYPES.SPEED);if(this.left){this.rotationSpeed+=-Constants.TANK.ROTATION_SPEED*speedModifier;}if(this.right){this.rotationSpeed+=Constants.TANK.ROTATION_SPEED*speedModifier;}}});if(typeof module==='object'){module.exports=Tank;}